  export default "import React from 'react';\nimport { Button, Space } from '@sqi-ui/web';\nimport Portal from '../Portal';\n\nexport default function Demo() {\n  const [open1, setOpen1] = React.useState(false);\n  const btnRef = React.useRef<HTMLButtonElement>(null);\n  const [open2, setOpen2] = React.useState(false);\n\n  return (\n    <>\n      <Space>\n        <Button type=\"primary\" onClick={() => setOpen1(!open1)}>\n          open\n        </Button>\n        <Button ref={btnRef} type=\"primary\" onClick={() => setOpen2(!open2)}>\n          custom append container\n        </Button>\n      </Space>\n\n      <Portal open={open1}>\n        <div\n          style={{\n            position: 'absolute',\n            top: 0,\n            left: 0,\n            zIndex: 1000,\n            background: 'red',\n            padding: 20,\n            color: 'white',\n          }}\n        >\n          Base append content\n        </div>\n      </Portal>\n\n      <Portal open={open2} getContainer={() => btnRef.current}>\n        <div\n          style={{\n            position: 'absolute',\n            top: 0,\n            right: 0,\n            zIndex: 1000,\n            background: 'red',\n            padding: 20,\n            color: 'white',\n          }}\n        >\n          Append dom position in Button\n        </div>\n      </Portal>\n    </>\n  );\n}\n";;
  