  export default "import * as React from 'react';\nimport { Button, Checkbox, Space } from '@sqi-ui/web';\nimport CSSMotionList, { CSSMotionListItem, type CSSMotionListInstance } from '../CSSMotionList';\nimport './motion-list.css';\n\nexport default function Demo() {\n  const motionRef = React.useRef<CSSMotionListInstance>(null);\n  const [list, setList] = React.useState<string[]>([]);\n  const [autoClose, setAutoClose] = React.useState(false);\n\n  const add = () => {\n    const newItem = `ListItem${list.length + 1}`;\n    const newList = [...list, newItem];\n    setList(newList);\n\n    requestAnimationFrame(() => {\n      motionRef.current?.toggle(newItem, true);\n    });\n    if (autoClose) {\n      setTimeout(() => {\n        motionRef.current?.toggle(newItem, false);\n      }, 2000);\n    }\n  };\n  const clear = () => {\n    // setList([]);\n    motionRef.current?.toggleAll(false);\n  };\n\n  return (\n    <>\n      <Space>\n        <Button type=\"primary\" onClick={add}>\n          Add\n        </Button>\n        <Button type=\"primary\" onClick={clear}>\n          Clear\n        </Button>\n        <Checkbox checked={autoClose} onChange={(e) => setAutoClose(e.target.checked)}>\n          Auto Close\n        </Checkbox>\n      </Space>\n      <div className=\"list-item-container\">\n        <CSSMotionList ref={motionRef} name=\"demo-list\" mountOnEnter preEnter unmountOnExit timeout={250}>\n          {({ prefixCls, ...transitionStatus }) => {\n            return list.map((item) => (\n              <CSSMotionListItem prefixCls={prefixCls} {...transitionStatus} itemKey={item} key={item}>\n                <div className=\"list-item\">{item}</div>\n              </CSSMotionListItem>\n            ));\n          }}\n        </CSSMotionList>\n      </div>\n    </>\n  );\n}\n";;
  